={{ (() => {
  const district = $fromAI(
    'district_term',
    'Фрагмент названия района или округа Московской области из запроса и истории диалога. Например: талдомск. Без слов район, округ, область и без символов подстановки.',
    'string'
  ).trim();

  const maxPrice = $fromAI(
    'max_price_exclusive',
    'Верхняя граница начальной цены в рублях, строго не включительно. Например, дешевле 500 тысяч означает 500000. Бери только из запроса пользователя или истории; не придумывай.',
    'number'
  );

  if (
    district.length < 3 ||
    district.length > 80 ||
    /[%_\\\r\n]/.test(district)
  ) {
    throw new Error('Некорректное название района для SQL-поиска.');
  }

  if (!Number.isFinite(maxPrice) || maxPrice <= 0) {
    throw new Error('Для SQL-поиска нужна положительная граница цены.');
  }

  return [
    '50',
    district,
    'sale',
    JSON.stringify('2.2'),
    maxPrice
  ];
})() }}

