={{ (() => {
  const f = $fromAI(
    'filters',
    'Объект фильтров поиска по текущему запросу и истории диалога. ' +
    'Обязательно передай ровно 8 полей: district_term, transaction_type, ' +
    'permitted_use_code, min_price, max_price_exclusive, min_area_m2, ' +
    'max_area_m2, only_open. ' +
    'Для первых семи полей отсутствие ограничения обозначай null, не строкой. ' +
    'district_term: фрагмент названия района, например талдомск. ' +
    'transaction_type: sale, rent или null. ' +
    'permitted_use_code: строковый код; ИЖС — 2.1, приусадебное ЛПХ — 2.2. ' +
    'Цены передавай числами в рублях, площади — числами в квадратных метрах. ' +
    'Минимальная цена включительно; максимальная цена строго не включительно. ' +
    'Обе границы площади включительно. ' +
    'only_open: обязательно boolean true или false. ' +
    'true означает одновременно: статус APPLICATIONS_SUBMISSION, is_active=1 ' +
    'и срок подачи заявок позже текущего времени UTC по данным базы. ' +
    'Включай true, если пользователь просит только открытый приём заявок, ' +
    'лоты с неистёкшим сроком или действующие торги. ' +
    'Это не подтверждает фактический статус торгов на внешней площадке. ' +
    'false отключает эти три проверки и не означает поиск только закрытых лотов. ' +
    'При уточнении поиска сохраняй предыдущие ограничения, включая only_open, ' +
    'если пользователь не изменил или не отменил их. ' +
    'Для нового поиска без требования открытого приёма заявок используй false. ' +
    'Не придумывай ограничения.',
    'json'
  );

  const keys = [
    'district_term',
    'transaction_type',
    'permitted_use_code',
    'min_price',
    'max_price_exclusive',
    'min_area_m2',
    'max_area_m2',
    'only_open'
  ];

  if (!f || typeof f !== 'object' || Array.isArray(f)) {
    throw new Error('Фильтры должны быть JSON-объектом.');
  }

  const actualKeys = Object.keys(f);

  if (
    actualKeys.length !== keys.length ||
    keys.some(k => !actualKeys.includes(k))
  ) {
    throw new Error(
      'Передайте ровно 8 предусмотренных полей фильтров.'
    );
  }

  let district = f.district_term;

  if (district !== null) {
    if (typeof district !== 'string') {
      throw new Error('Район должен быть строкой или null.');
    }

    district = district.trim();

    if (
      district.length < 3 ||
      district.length > 80 ||
      /[%_\\\r\n]/.test(district)
    ) {
      throw new Error('Некорректное название района.');
    }
  }

  if (![null, 'sale', 'rent'].includes(f.transaction_type)) {
    throw new Error('Тип сделки: sale, rent или null.');
  }

  const allowedCodes = [
    '2.1',
    '2.2',
    '2.3',
    '2.1.2001',
    '2.7.2001',
    '3.1',
    '3.1.2002',
    '3.2.2003',
    '3.4.2001',
    '3.6.2001',
    '4.1',
    '4.4',
    '4.6'
  ];

  if (
    f.permitted_use_code !== null &&
    !allowedCodes.includes(f.permitted_use_code)
  ) {
    throw new Error('Неподдерживаемый код назначения.');
  }

  const numericKeys = [
    'min_price',
    'max_price_exclusive',
    'min_area_m2',
    'max_area_m2'
  ];

  for (const k of numericKeys) {
    const value = f[k];

    if (
      value !== null &&
      (
        typeof value !== 'number' ||
        !Number.isFinite(value) ||
        value < 0
      )
    ) {
      throw new Error(
        k + ': требуется неотрицательное число или null.'
      );
    }
  }

  if (
    f.min_price !== null &&
    f.max_price_exclusive !== null &&
    f.min_price >= f.max_price_exclusive
  ) {
    throw new Error('Некорректный диапазон цены.');
  }

  if (
    f.min_area_m2 !== null &&
    f.max_area_m2 !== null &&
    f.min_area_m2 > f.max_area_m2
  ) {
    throw new Error('Некорректный диапазон площади.');
  }

  if (typeof f.only_open !== 'boolean') {
    throw new Error(
      'only_open должен быть boolean true или false.'
    );
  }

  return [
    '50',
    district,
    f.transaction_type,
    f.permitted_use_code === null
      ? null
      : JSON.stringify(f.permitted_use_code),
    f.min_price,
    f.max_price_exclusive,
    f.min_area_m2,
    f.max_area_m2,
    f.only_open ? 1 : 0
  ];
})() }}

